import { test, expect } from '@playwright/test';

test.describe('Dropdown Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should close dropdown when Escape key is pressed', async ({ page }) => {
    await page.getByRole('button', { name: /open dropdown/i }).click();
    await expect(page.getByRole('listbox')).toBeVisible();

    await page.keyboard.press('Escape');
    await expect(page.getByRole('listbox')).not.toBeVisible();
  });

  test('should not close dropdown when other keys are pressed', async ({ page }) => {
    await page.getByRole('button', { name: /open dropdown/i }).click();
    await expect(page.getByRole('listbox')).toBeVisible();

    await page.keyboard.press('Enter');
    await expect(page.getByRole('listbox')).toBeVisible();
  });
});
